/**
 * Generates components/xterm-bundle.ts — a self-contained HTML document
 * with xterm.js + addon-fit + CSS inlined, so the terminal WebView works
 * fully offline (no CDN). Re-run after bumping the @xterm/* deps:
 *
 *   node scripts/gen-xterm-bundle.js
 */
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..'); // mobile/
const read = (p) => fs.readFileSync(path.join(root, p), 'utf8');

const xtermCss = read('node_modules/@xterm/xterm/css/xterm.css');
const xtermJs = read('node_modules/@xterm/xterm/lib/xterm.js');
const fitJs = read('node_modules/@xterm/addon-fit/lib/addon-fit.js');

const initScript = `
  function post(m){ try { window.ReactNativeWebView.postMessage(JSON.stringify(m)); } catch(e){} }
  function boot() {
    if (typeof Terminal === 'undefined') { post({ type:'error', message:'xterm missing' }); return; }
    var term = new Terminal({
      fontSize: 12,
      fontFamily: 'Menlo, Monaco, monospace',
      cursorBlink: true,
      scrollback: 4000,
      theme: {
        background:'#0a0a0c', foreground:'#d4d4d8', cursor:'#3b82f6',
        black:'#3f3f46', red:'#ef4444', green:'#22c55e', yellow:'#eab308',
        blue:'#3b82f6', magenta:'#a855f7', cyan:'#06b6d4', white:'#d4d4d8',
        brightBlack:'#71717a', brightRed:'#f87171', brightGreen:'#4ade80',
        brightYellow:'#facc15', brightBlue:'#60a5fa', brightMagenta:'#c084fc',
        brightCyan:'#22d3ee', brightWhite:'#fafafa'
      }
    });
    var fit = new FitAddon.FitAddon();
    term.loadAddon(fit);
    term.open(document.getElementById('t'));
    function doFit(){ try { fit.fit(); post({ type:'resize', cols:term.cols, rows:term.rows }); } catch(e){} }
    term.onData(function(d){ post({ type:'data', data:d }); });
    window.addEventListener('resize', doFit);
    window.__recv = function(json){
      try { var m = JSON.parse(json);
        if (m.type==='write') term.write(m.data);
        else if (m.type==='reset') term.reset();
        else if (m.type==='fit') doFit();
      } catch(e){}
    };
    setTimeout(doFit, 60);
    post({ type:'ready' });
  }
  boot();
`;

const html = `<!DOCTYPE html>
<html>
<head>
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
<style>
html,body{height:100%;margin:0;background:#0a0a0c;overflow:hidden}
#t{height:100%;width:100%;padding:6px;box-sizing:border-box}
.xterm-viewport::-webkit-scrollbar{width:0;height:0}
${xtermCss}
</style>
</head>
<body>
<div id="t"></div>
<script>${xtermJs}</script>
<script>${fitJs}</script>
<script>${initScript}</script>
</body>
</html>`;

const out = path.join(root, 'components/xterm-bundle.ts');
fs.writeFileSync(
  out,
  '// AUTO-GENERATED by scripts/gen-xterm-bundle.js — do not edit by hand.\n' +
  '// Inlines xterm.js + addon-fit + css for fully-offline terminal rendering.\n' +
  '/* eslint-disable */\n' +
  'export const TERMINAL_HTML = ' + JSON.stringify(html) + ';\n',
);
console.log(`Wrote ${out} (${(html.length / 1024).toFixed(0)} KB inlined)`);
